'use strict';
const MODEL=JSON.parse(document.getElementById('model').textContent);
const {FIELDS,CHOICES,CATEGORY_LABELS,TITLES,ORG,VERSION}=MODEL;
const TABLES=['owners','assets','ownerships','actions','cases','documents','utilities','options'];
const CONFIG=JSON.parse(document.getElementById('deployment-config').textContent);
const BUCKET='bg-estate-documents',DEMO_KEY='balkan-imovina-demo-v1',CONFIG_KEY='balkan-imovina-config-v1';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const uid=()=>crypto.randomUUID();
let D=Object.fromEntries([...TABLES,'profiles','audit_log'].map(k=>[k,[]]));
let state={route:'dashboard',asset:null,tab:'overview',filters:{},q:'',page:1,report:'holdings',showFilters:true,adminTab:'options',category:'asset_type',demo:false,profile:null,org:{id:ORG,name:'Balkan grupa',warning_days:30},lastSync:null};
let client=null,modal=null,authBusy=false,loading=false,recovery=false,currentConfig=null,focusBeforeModal=null,dirty=false,savingRecord=false,authSubscription=null;
const canWrite=()=>['admin','editor'].includes(state.profile?.role),isAdmin=()=>state.profile?.role==='admin';
const ownerName=id=>D.owners.find(x=>x.id===id)?.full_name??'—';
const assetName=id=>D.assets.find(x=>x.id===id)?.name??'Nepoznata nepokretnost';
const assetCode=id=>D.assets.find(x=>x.id===id)?.code??'—';
const number=(v,dec=2)=>v==null?'—':new Intl.NumberFormat('sr-Latn-RS',{minimumFractionDigits:dec,maximumFractionDigits:dec}).format(v);
const money=(v,c)=>v==null?'—':number(v)+' '+(c??'');
const date=v=>v?new Intl.DateTimeFormat('sr-Latn-RS',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Europe/Belgrade'}).format(new Date(v.length===10?v+'T12:00:00':v)):'—';
const percent=v=>v==null?'—':number(v*100)+'%';
const countNoun=(n,one,few,many)=>n+' '+(n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many);
const badge=(s,tone='')=>`<span class="badge ${tone}">${esc(s)}</span>`;
const b=(text,action,args='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${args}>${text}</button>`;
const noData=(text='Nema unetih podataka.',sub='')=>`<div class="empty"><h3>${esc(text)}</h3><div class="small">${esc(sub)}</div></div>`;
const optionTag=(v,s,selected)=>`<option value="${esc(v)}"${String(v)===String(selected)?' selected':''}>${esc(s)}</option>`;
const options=(kind,value,empty='Sve',inactive=false)=>optionTag('',empty,value)+D.options.filter(o=>o.kind===kind&&(inactive||o.active||o.code===value)).sort((a,b)=>a.sort_order-b.sort_order||a.label.localeCompare(b.label,'sr')).map(o=>optionTag(o.code,o.label+(o.active?'':' (neaktivno)'),value)).join('');
const link=(url,text)=>safeUrl(url)?`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`:'—';
function toast(text,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=text;$('#toasts').append(e);setTimeout(()=>e.remove(),error?9000:4500);}
function friendly(error){const s=error?.message??String(error);if(/row-level|permission|42501|not allowed/i.test(s))return 'Nemate ovlašćenje za ovu izmenu.';if(/duplicate key|23505/i.test(s))return 'ID ili veza već postoji. Osvežite podatke i proverite unos.';if(/foreign key|23503/i.test(s))return 'Stavka je povezana sa drugim podacima. Uklonite veze ili arhivirajte nepokretnost.';if(/Failed to fetch|Network|timeout|AbortError/i.test(s))return 'Veza sa bazom nije dostupna. Izmena nije potvrđena. Proverite vezu i osvežite podatke.';if(/Invalid login/i.test(s))return 'Pogrešan e-mail ili lozinka.';return s;}
function download(name,content,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function dayOffset(n){const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function seedDemo(){
 const options=Object.entries(CHOICES).flatMap(([kind,rows])=>rows.map(([code,label,flags={}],i)=>({id:uid(),org_id:ORG,kind,code,label,flags,sort_order:i,active:true,version:1})));
 const owners=[{id:uid(),code:'VLA-001',full_name:'Balkan avto – DEMO',kind:'legal',country:'RS',within_group:true,active:true},{id:uid(),code:'VLA-002',full_name:'Balkan transport – DEMO',kind:'legal',country:'SI',within_group:true,active:true},{id:uid(),code:'VLA-003',full_name:'Fizičko lice – DEMO',kind:'natural',country:'RS',within_group:true,active:true},{id:uid(),code:'VLA-004',full_name:'Spoljni suvlasnik – DEMO',kind:'legal',country:'RS',within_group:false,active:true}];
 const asset=(i,name,city,type,owner,permit,extra={})=>({id:uid(),org_id:ORG,code:'NEK-'+String(i).padStart(3,'0'),name,city,asset_type:type,lead_owner_id:owner.id,occupancy_permit:permit,country:'RS',portfolio_status:'portfolio',usage_status:'own',priority:'medium',cadastral_municipality:city+' – DEMO',parcel_number:`${1000+i}/1`,registration_status:'registered',construction_permit:'yes',proceedings_status:'na',encumbrances:'no',currency:'EUR',reviewed_on:today(),notes:'DEMO PODACI. Ova nepokretnost je izmišljena i služi isključivo za proveru aplikacije.',version:1,...extra});
 const assets=[asset(1,'Poslovno-servisni kompleks','Šabac','warehouse',owners[0],'no',{address:'Primer adrese 1',market_value:1200000,net_area:1800,land_area:4200,proceedings_status:'pending',priority:'high'}),asset(2,'Poslovni prostor','Beograd','office',owners[2],'yes',{market_value:280000,net_area:135,usage_status:'rented',monthly_rent:1800,tenant:'Primer zakupca – DEMO'}),asset(3,'Građevinsko zemljište','Dobanovci','building_land',owners[0],'na',{market_value:600000,land_area:5600,usage_status:'vacant'}),asset(4,'Logistički objekat','Brežice','warehouse',owners[1],'yes',{country:'SI',market_value:950000,net_area:1200}),asset(5,'Objekat u rekonstrukciji','Novi Sad','building',owners[2],'pending',{market_value:null,usage_status:'renovation',proceedings_status:'supplement',registration_status:'partial'}),asset(6,'Parking i plato','Šabac','parking',owners[0],'unknown',{currency:'RSD',market_value:24000000,land_area:1500})];
 const share=(a,o,n=1,den=1)=>({id:uid(),org_id:ORG,asset_id:a.id,owner_id:o.id,numerator:n,denominator:den,version:1});
 const ownerships=[share(assets[0],owners[0]),share(assets[1],owners[2],1,2),share(assets[1],owners[3],1,2),share(assets[2],owners[0]),share(assets[3],owners[1]),share(assets[4],owners[2]),share(assets[5],owners[0])];
 const actions=[{id:uid(),asset_id:assets[0].id,position:1,description:'Pribaviti upotrebnu dozvolu',responsible:'Odgovorno lice – DEMO',due_date:dayOffset(-3),status:'in_progress',version:1},{id:uid(),asset_id:assets[0].id,position:2,description:'Dopuniti dokumentaciju za upis',due_date:dayOffset(15),status:'not_started',version:1},{id:uid(),asset_id:assets[4].id,position:1,description:'Dostaviti dopunu elaborata',due_date:dayOffset(7),status:'documents',version:1}];
 const cases=[{id:uid(),asset_id:assets[0].id,system:'ceop',case_number:'DEMO-CEOP-001',case_type:'occupancy',status:'processing',external_status:'Primer statusa za demonstraciju',checked_on:today(),deadline:dayOffset(8),version:1},{id:uid(),asset_id:assets[4].id,system:'cadastre',case_number:'DEMO-KAT-002',case_type:'building_registration',status:'supplement',checked_on:dayOffset(-7),deadline:dayOffset(-1),version:1}];
 return {...Object.fromEntries([...TABLES,'profiles','audit_log'].map(k=>[k,[]])),options,owners,assets,ownerships,actions,cases,documents:[{id:uid(),code:'DOC-001',asset_id:assets[0].id,title:'Primer poreskog rešenja',document_type:'tax',status:'exists',expires_on:dayOffset(20),version:1}],utilities:[{id:uid(),asset_id:assets[0].id,utility_type:'electricity',supplier:'Primer dobavljača',customer_code:'00012345',meter_number:'001234',power_kw:600,version:1}]};
}
function persistDemo(){try{localStorage.setItem(DEMO_KEY,JSON.stringify(D));}catch{throw new Error('Nema dovoljno prostora za demo podatke u pregledaču.');}}
function enterDemo(){state.demo=true;try{D=JSON.parse(localStorage.getItem(DEMO_KEY))||seedDemo();}catch{D=seedDemo();}state.profile={id:'demo-admin',display_name:'Demo administrator',role:'admin',active:true,org_id:ORG};state.lastSync=new Date();state.route='dashboard';render();}
async function loadSdk(){if(window.supabase?.createClient)return;if($('#sdk-loader'))throw new Error('Povezivanje je u toku.');await new Promise((resolve,reject)=>{const e=document.createElement('script');e.id='sdk-loader';e.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.119.0/dist/umd/supabase.js';e.crossOrigin='anonymous';e.onload=resolve;e.onerror=()=>{e.remove();reject(new Error('Supabase biblioteka nije učitana. Proverite internet vezu.'));};document.head.append(e);});}
async function connect(config){currentConfig=validateConfig(config.url,config.key);await loadSdk();if(client){client.auth.stopAutoRefresh();authSubscription?.unsubscribe();}client=window.supabase.createClient(currentConfig.url,currentConfig.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storage:sessionStorage,storageKey:'balkan-imovina-auth-'+new URL(currentConfig.url).hostname},global:{fetch:(url,init={})=>fetch(url,{...init,signal:init.signal??AbortSignal.timeout(25000)})}});authSubscription=client.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){recovery=true;setTimeout(()=>renderRecovery(),0);}else if(event==='SIGNED_OUT'){state.profile=null;D=Object.fromEntries([...TABLES,'profiles','audit_log'].map(k=>[k,[]]));renderLogin();}else if(event==='SIGNED_IN'&&!state.profile&&!recovery){setTimeout(()=>startSession().catch(e=>toast(friendly(e),true)),0);}}).data.subscription;const {data,error}=await client.auth.getSession();if(error)throw error;if(data.session&&!recovery)await startSession();else renderLogin();}
async function listAll(table){const result=[];for(let from=0;from<50000;from+=1000){const {data,error}=await client.from('bg_'+table).select('*').eq('org_id',state.profile.org_id).order('id').range(from,from+999);if(error)throw error;result.push(...data);if(data.length<1000)return result;}throw new Error('Tabela premašuje 50.000 stavki. Potrebna je serverska paginacija za veći obim. Prikaz nije skraćen.');}
async function startSession(){if(authBusy)return;authBusy=true;try{const {data:u,error:ue}=await client.auth.getUser();if(ue)throw ue;const {data:p,error}=await client.from('bg_profiles').select('*').eq('id',u.user.id).single();if(error)throw error;state.demo=false;state.profile=p;if(!p.active){renderPending();return;}await reload();}finally{authBusy=false;}}
async function reload(){if(state.demo){state.lastSync=new Date();render();return;}if(loading)return;loading=true;try{const {data:freshProfile,error:profileError}=await client.from('bg_profiles').select('*').eq('id',state.profile.id).single();if(profileError)throw profileError;state.profile=freshProfile;if(!freshProfile.active){D=Object.fromEntries([...TABLES,'profiles','audit_log'].map(k=>[k,[]]));renderPending();return;}if(!isAdmin()){D.profiles=[];D.audit_log=[];}const {data:org,error}=await client.from('bg_organizations').select('*').eq('id',state.profile.org_id).single();if(error)throw error;const rows=await Promise.all(TABLES.map(k=>listAll(k)));const fresh=Object.fromEntries(TABLES.map((k,i)=>[k,rows[i]]));if(!fresh.options.length)throw new Error('Liste nisu inicijalizovane. Pokrenite priloženi SQL za bazu.');D={...D,...fresh};state.org=org;if(isAdmin()){const {data:p,error:e}=await client.from('bg_profiles').select('*').eq('org_id',org.id).order('email');if(e)throw e;D.profiles=p;}state.lastSync=new Date();render();}finally{loading=false;}}
async function saveRecord(table,row,existing){if(!canWrite())throw new Error('Nemate ovlašćenje za izmenu.');if(table==='options'&&!isAdmin())throw new Error('Samo administrator uređuje liste.');if(state.demo){const value={...existing,...row,id:existing?.id??uid(),org_id:ORG,version:(existing?.version??0)+1,updated_at:new Date().toISOString()};const idx=D[table].findIndex(x=>x.id===value.id);if(idx>=0)D[table][idx]=value;else D[table].push(value);D.audit_log.unshift({id:uid(),entity:'bg_'+table,entity_id:value.id,operation:existing?'UPDATE':'INSERT',actor_name:'Demo administrator',created_at:new Date().toISOString(),old_data:existing??null,new_data:value});persistDemo();return value;}
 let q=client.from('bg_'+table);q=existing?q.update(row).eq('id',existing.id).eq('org_id',state.profile.org_id).eq('version',existing.version):q.insert({...row,org_id:state.profile.org_id});const {data,error}=await q.select().maybeSingle();if(error)throw error;if(!data)throw new Error('Podatak je u međuvremenu izmenjen ili pristup nije dozvoljen. Sačuvajte svoj tekst, osvežite podatke i ponovite izmenu.');const idx=D[table].findIndex(x=>x.id===data.id);if(idx>=0)D[table][idx]=data;else D[table].push(data);return data;
}
async function removeRecord(table,id){if(!isAdmin())throw new Error('Samo administrator briše podatke.');const r=D[table].find(x=>x.id===id);if(!r)return;if(!confirm('Trajno obrisati ovu stavku? Ova radnja se evidentira u istoriji izmena.'))return;if(state.demo){if(table==='assets'&&['ownerships','actions','cases','documents','utilities'].some(t=>D[t].some(x=>x.asset_id===id)))throw new Error('Nepokretnost ima povezane podatke. Koristite arhiviranje.');if(table==='owners'&&(D.ownerships.some(x=>x.owner_id===id)||D.assets.some(x=>x.lead_owner_id===id)||D.utilities.some(x=>x.contract_owner_id===id)))throw new Error('Vlasnik je povezan sa nepokretnostima. Deaktivirajte vlasnika.');D[table]=D[table].filter(x=>x.id!==id);persistDemo();}else{const {data,error}=await client.from('bg_'+table).delete().eq('id',id).eq('org_id',state.profile.org_id).eq('version',r.version).select('id');if(error)throw error;if(!data?.length)throw new Error('Stavka je promenjena. Osvežite podatke.');D[table]=D[table].filter(x=>x.id!==id);if(table==='documents'&&r.storage_path){try{const {error:e}=await client.storage.from(BUCKET).remove([r.storage_path]);if(e)throw e;}catch{toast('Zapis je obrisan. Datoteka nije uklonjena iz Storage-a; administrator treba da je proveri.',true);}}}if(table==='assets'&&state.asset===id){state.asset=null;state.route='assets';}render();toast('Stavka je obrisana.');}
function shell(content){const nav=[['dashboard','Pregled'],['assets','Nepokretnosti'],['cases','CEOP / katastar'],['actions','Naredni koraci'],['owners','Vlasnici'],['ownerships','Suvlasništvo'],['documents','Dokumentacija'],['utilities','Komunalije'],['reports','Izveštaji']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">BALKAN<small>IMOVINA</small></div><div class="nav-label">Evidencija</div>${nav.map(([id,s])=>`<button class="nav-btn ${state.route===id?'active':''}" data-action="nav" data-route="${id}">${s}</button>`).join('')}${isAdmin()?'<div class="nav-label">Upravljanje</div><button class="nav-btn '+(state.route==='admin'?'active':'')+'" data-action="nav" data-route="admin">Administracija</button>':''}<div class="sidebar-bottom"><div class="profile-box"><div class="profile-name">${esc(state.profile?.display_name||state.profile?.email)}</div><div class="small muted">${({admin:'Administrator',editor:'Urednik',viewer:'Pregled'})[state.profile?.role]}</div><div class="row" style="margin-top:12px">${b('Nalog','account','','small quiet')}${b('Odjava','logout','','small quiet')}</div></div></div></aside><div class="workspace">${state.demo?'<div class="demo-bar"><span><b>DEMO</b> · Izmišljeni podaci. Čuvaju se samo u ovom pregledaču.</span><button data-action="exit-demo">Poveži stvarnu bazu</button></div>':''}<div id="offline" class="offline-bar ${navigator.onLine?'hidden':''}">Internet veza nije dostupna. Produkcijske izmene nisu sačuvane.</div><header class="topbar"><div class="row">${b('☰','menu','','quiet mobile-menu')}<span class="crumb">${esc(state.org.name)} <span class="muted">/</span> <strong>${esc(state.route==='dashboard'?'Pregled':state.route==='reports'?'Izveštaji':state.route==='admin'?'Administracija':TITLES[state.route]??'Evidencija')}</strong></span></div><div class="row"><span class="small muted sync-label">${state.lastSync?'Osveženo '+new Intl.DateTimeFormat('sr-Latn-RS',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Belgrade'}).format(state.lastSync):''}</span>${b('Osveži','refresh','','small')}</div></header><main class="main">${content}<div class="footer-note">Balkan Imovina ${VERSION} · ${date(today())} · Europe/Belgrade</div></main></div></div>`;}
function heading(title,subtitle,buttons=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="row">${buttons}</div></div>`;}
function render(){if(!state.profile?.active){renderLogin();return;}if(state.route==='dashboard')renderDashboard();else if(state.route==='assets'&&state.asset)renderAsset();else if(state.route==='assets')renderAssets();else if(state.route==='reports')renderReports();else if(state.route==='admin')renderAdmin();else renderEntities(state.route);}
function nav(route){state.route=route;state.asset=null;state.q='';state.page=1;state.filters={};render();window.scrollTo(0,0);}
function goAsset(id,tab='overview'){state.route='assets';state.asset=id;state.tab=tab;render();window.scrollTo(0,0);}
function renderDashboard(){const portfolio=filterAssets(D,{mode:'portfolio'}),noPermit=D.assets.filter(x=>x.occupancy_permit==='no'),progress=D.assets.filter(a=>inProgress(D,a));const lateSteps=D.actions.filter(x=>late(D,x,'due_date','action_status')),lateCases=D.cases.filter(x=>late(D,x,'deadline','case_status'));const warnings=[...lateSteps.map(x=>({id:x.asset_id,text:x.description,meta:`Korak ${x.position} · ${date(x.due_date)}`,tab:'actions'})),...lateCases.map(x=>({id:x.asset_id,text:x.case_number,meta:`Predmet · ${date(x.deadline)}`,tab:'cases'}))];const moneyRows=totals(D,portfolio);shell(heading('Pregled nepokretnosti','Vlasništvo, pravni statusi i naredne aktivnosti na jednom mestu.',canWrite()?b('+ Nova nepokretnost','new','data-table="assets"','primary'):'')+`<div class="cards">${[['U portfelju',portfolio.length,'portfolio','Uključuje nepokretnosti u prodaji'],['U postupku',progress.length,'progress','Otvoreni predmeti i postupci'],['Bez upotrebne dozvole',noPermit.length,'no_permit','Izričito označene sa „Nema“'],['Koraci u kašnjenju',lateSteps.length,'overdue','Otvorene aktivnosti sa isteklim rokom']].map(([s,n,mode,sub])=>`<div class="stat"><div class="stat-label">${s}</div><div class="stat-value"><button class="link-btn" data-action="quick-filter" data-mode="${mode}">${n}</button></div><div class="stat-foot">${sub}</div></div>`).join('')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Rokovi koji traže pažnju</h2>${badge(warnings.length+' stavki',warnings.length?'red':'')}</div><div class="panel-body">${warnings.length?`<div class="action-list">${warnings.slice(0,7).map(x=>`<div class="action-item"><div><button class="link-btn action-title" data-action="asset" data-id="${x.id}" data-tab="${x.tab}">${esc(x.text)}</button><div class="action-meta">${esc(assetName(x.id))} · ${x.meta}</div></div>${badge('Kasni','red')}</div>`).join('')}</div>`:noData('Nema dospelih otvorenih obaveza.','Novi rokovi će se pojaviti nakon unosa koraka i predmeta.')}</div></section><section class="panel"><div class="panel-head"><h2>Procenjena vrednost portfelja</h2>${b('Izveštaji','nav','data-route="reports"','small')}</div><div class="panel-body"><div class="money-pair">${moneyRows.map(x=>`<div><div class="small muted">${x.currency} · 100% nepokretnosti</div><div class="kpi-money">${number(x.market)}</div><div class="small muted">Udeo grupe: <strong>${number(x.group)}</strong></div><div class="subline">Zakup mesečno: ${money(x.rent,x.currency)}</div></div>`).join('')}</div><p class="small muted">Valute su odvojene. Vrednost udela grupe obuhvata samo nepokretnosti sa potpuno unetim vlasničkim udelima.</p>${badge(D.assets.filter(a=>!shares(D,a.id).complete).length+' nepotpunih evidencija udela','amber')}</div></section></div><section class="panel"><div class="panel-head"><h2>Pregled po statusu</h2>${b('Sve nepokretnosti','nav','data-route="assets"','small')}</div><div class="panel-body"><div class="row">${D.options.filter(o=>o.kind==='portfolio_status').map(o=>b(`${esc(o.label)} <b>${D.assets.filter(a=>a.portfolio_status===o.code).length}</b>`,'status-filter',`data-status="${o.code}"`,'')).join('')}</div><div class="hr"></div><div class="row">${badge(D.cases.filter(x=>!closed(D,'case_status',x.status)).length+' otvorenih predmeta','blue')}${badge(D.documents.filter(x=>x.expires_on&&x.expires_on<today()).length+' dokumenata sa isteklim rokom','amber')}${badge(D.assets.filter(x=>x.occupancy_permit==='unknown').length+' neproverenih upotrebnih dozvola','amber')}</div></div></section>`);}
function filterPanel(){const f=state.filters;const entries=[['owner','Vlasnik / bilo koji suvlasnik',optionTag('','Svi vlasnici',f.owner)+D.owners.map(o=>optionTag(o.id,o.full_name,f.owner)).join('')],['city','Grad',optionTag('','Svi gradovi',f.city)+[...new Set(D.assets.map(a=>a.city))].sort((a,b)=>a.localeCompare(b,'sr')).map(c=>optionTag(c,c,f.city)).join('')],['asset_type','Vrsta',options('asset_type',f.asset_type)],['portfolio_status','Status evidencije',options('portfolio_status',f.portfolio_status)],['usage_status','Korišćenje',options('usage_status',f.usage_status)],['occupancy_permit','Upotrebna dozvola',options('permit_status',f.occupancy_permit)],['country','Država',options('country',f.country)],['mode','Poseban pregled',[['','Sve nepokretnosti'],['portfolio','U portfelju i prodaji'],['progress','U postupku'],['no_permit','Bez upotrebne dozvole'],['unknown_permit','Dozvola nepoznata'],['overdue','Koraci u kašnjenju'],['shares','Nepotpuni vlasnički udeli']].map(([v,s])=>optionTag(v,s,f.mode)).join('')]];return `<div class="filter-grid ${state.showFilters?'':'hidden'}">${entries.map(([k,s,html])=>`<div><label for="filter-${k}">${s}</label><select id="filter-${k}" data-filter="${k}">${html}</select></div>`).join('')}</div>`;}
function assetTable(rows,paginated=true){const start=(state.page-1)*25,show=paginated?rows.slice(start,start+25):rows;return rows.length?`<div class="table-wrap"><table><thead><tr><th>Nepokretnost</th><th>Grad / KO / parcela</th><th>Vlasnik</th><th>Status / korišćenje</th><th>Upotrebna dozvola</th><th>Naredni korak</th><th></th></tr></thead><tbody>${show.map(a=>{const next=openSteps(D,a.id)[0];return `<tr><td><button class="link-btn" data-action="asset" data-id="${a.id}">${esc(a.name)}</button><div class="subline mono">${esc(a.code)} · ${esc(lbl(D,'asset_type',a.asset_type))}</div></td><td>${esc(a.city)}<div class="subline">${esc(a.cadastral_municipality||'KO nije uneta')}<br>Parcela ${esc(a.parcel_number||'—')}</div></td><td>${esc(ownerName(a.lead_owner_id))}<div class="subline">${countNoun(shares(D,a.id).rows.length,'vlasnik','vlasnika','vlasnika')}</div></td><td>${badge(lbl(D,'portfolio_status',a.portfolio_status),'blue')}<div class="subline">${esc(lbl(D,'usage_status',a.usage_status))}</div></td><td>${badge(lbl(D,'permit_status',a.occupancy_permit),a.occupancy_permit==='no'?'red':a.occupancy_permit==='yes'?'green':'amber')}</td><td>${next?`${esc(next.description)}<div class="subline">${badge(date(next.due_date),late(D,next,'due_date','action_status')?'red':'')} ${esc(next.responsible||'')}</div>`:'<span class="muted">'+(steps(D,a.id).length?'Koraci zatvoreni':'Nije unet plan')+'</span>'}</td><td>${b('Kartica','asset',`data-id="${a.id}"`,'small')}</td></tr>`;}).join('')}</tbody></table></div>${paginated?pager(rows.length):''}`:noData('Nema nepokretnosti za izabrane kriterijume.','Promenite filtere ili dodajte novu nepokretnost.');}
function pager(total){return `<div class="table-bottom"><span>${countNoun(total,'stavka','stavke','stavki')} · strana ${state.page} / ${Math.max(1,Math.ceil(total/25))}</span><div class="row">${b('Prethodna','page','data-dir="-1"'+(state.page<=1?' disabled':''),'small')}${b('Sledeća','page','data-dir="1"'+(state.page>=Math.ceil(total/25)?' disabled':''),'small')}</div></div>`;}
function renderAssets(){const rows=filterAssets(D,state.filters).sort((a,b)=>a.code.localeCompare(b.code,'sr'));shell(heading('Nepokretnosti','Pretraga obuhvata adresu, parcelu, KO, sve vlasnike, napomene i brojeve predmeta.',`${b('Štampa pregleda','print-list')}${b('CSV / Excel','export','data-table="assets"')}${canWrite()?b('+ Nova nepokretnost','new','data-table="assets"','primary'):''}`)+`<div class="toolbar"><div class="search"><input id="asset-search" type="search" data-search="assets" placeholder="Pretraži nepokretnosti, parcele, vlasnike, predmete…" value="${esc(state.filters.q||'')}" aria-label="Pretraga nepokretnosti"></div>${b('Filteri','filters')}${b('Očisti','clear-filters','','quiet')}</div><section class="panel"><div class="panel-head"><h2 id="asset-count">${countNoun(rows.length,'nepokretnost','nepokretnosti','nepokretnosti')}</h2><span class="small muted">Vlasnik uključuje sve suvlasnike</span></div>${filterPanel()}<div id="asset-results">${assetTable(rows)}</div></section>`);}
function displayField(f,v){const [k,,type,,,kind]=f;if(type==='select')return esc(lbl(D,kind,v));if(type==='owner')return esc(ownerName(v));if(type==='asset')return esc(assetCode(v)+' · '+assetName(v));if(type==='date')return date(v);if(type==='number')return number(v);if(type==='checkbox')return v?'Da':'Ne';if(type==='owner_kind')return v==='legal'?'Pravno lice':v==='natural'?'Fizičko lice':'—';if(type==='case_system')return ({ceop:'CEOP',cadastre:'Katastar',other:'Drugo'})[v]??'—';if(type==='url')return link(v,'Otvori link');return esc(v??'—');}
function detailFields(fields,row){return `<div class="detail-grid">${fields.filter(f=>f[2]!=='file').map(f=>`<div class="detail-item ${f[2]==='textarea'?'wide':''}"><label>${esc(f[1])}</label><div class="${f[2]==='textarea'?'preline':''}">${displayField(f,row[f[0]])}</div></div>`).join('')}</div>`;}
function renderAsset(){const a=D.assets.find(x=>x.id===state.asset);if(!a){state.asset=null;renderAssets();return;}const tabs=[['overview','Kartica'],['legal','Katastar i dozvole'],['finance','Finansije'],['ownerships','Vlasnici'],['actions','Pet koraka'],['cases','CEOP / katastar'],['documents','Dokumenti'],['utilities','Komunalije']];let content='';const s=shares(D,a.id);if(state.tab==='overview'){content=`<section class="panel"><div class="panel-head"><h2>Osnovni podaci</h2>${badge(lbl(D,'portfolio_status',a.portfolio_status),'blue')}</div><div class="panel-body">${detailFields(FIELDS.assets.filter(f=>f[3]==='Osnovno'),a)}<div class="hr"></div><div class="detail-item"><label>Napomena – slobodan unos</label><div class="preline">${esc(a.notes||'Nema napomene.')}</div></div></div></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Naredni korak</h2>${b('Plan koraka','asset-tab','data-tab="actions"','small')}</div><div class="panel-body">${openSteps(D,a.id)[0]?actionCards([openSteps(D,a.id)[0]]):noData('Nema otvorenih koraka.')}</div></section><section class="panel"><div class="panel-head"><h2>Vlasnički udeli</h2>${badge(s.complete?'Potpuno evidentirano':'Potrebna dopuna',s.complete?'green':'amber')}</div><div class="panel-body"><div class="row between"><span>Ukupno evidentirano</span><b>${percent(s.total)}</b></div><div class="hr"></div><div class="row between"><span>Udeo Balkan grupe</span><b>${percent(s.group)}</b></div><p class="small muted">Broj evidentiranih vlasnika: ${s.rows.length}. Vodeći vlasnik je samo oznaka za pregled.</p></div></section></div>`;}else if(['legal','finance'].includes(state.tab)){content=`<section class="panel"><div class="panel-head"><h2>${state.tab==='legal'?'Katastarski i pravni podaci':'Finansijski podaci'}</h2></div><div class="panel-body">${state.tab==='finance'?'<div class="notice">Svi uneti iznosi odnose se na 100% nepokretnosti. Troškovi komunalija se ne dodaju automatski održavanju.</div>':''}${detailFields(FIELDS.assets.filter(f=>f[3]===(state.tab==='legal'?'Katastar i dozvole':'Finansije')),a)}${state.tab==='finance'?`<div class="hr"></div><div class="detail-grid"><div class="detail-item"><label>Vrednost udela grupe</label><div>${s.complete&&a.market_value!=null?money(a.market_value*s.group,a.currency):'Nije raspoloživo – proverite procenu i udela.'}</div></div></div>`:''}</div></section>`;}else if(state.tab==='actions'){const rows=steps(D,a.id);content=`<div class="notice">Naredni korak je prvi nezavršen korak redom 1–5. Kašnjenja obuhvataju svih pet koraka. Za istoriju ranijih izmena administrator koristi evidenciju izmena.</div><div class="row between" style="margin-bottom:16px"><h2>Plan aktivnosti</h2>${canWrite()&&rows.length<5?b('+ Dodaj korak','new','data-table="actions"','primary'):''}</div>${rows.length?actionCards(rows):noData('Plan još nije unet.','Dodajte najviše pet tekućih koraka.')}`;}else{const t=state.tab;const rows=D[t].filter(x=>x.asset_id===a.id);content=`${t==='cases'?'<div class="notice">Statusi se unose ručno iz CEOP-a i katastra. Sačuvajte tačan tekst statusa, datum provere i link do izvornog predmeta.</div>':''}<section class="panel"><div class="panel-head"><h2>${TITLES[t]}</h2>${canWrite()?b('+ Dodaj','new',`data-table="${t}"`,'primary'):''}</div>${entityTable(t,rows,false)}</section>`;}
 shell(heading(a.name,`${a.code} · ${a.city} · ${lbl(D,'asset_type',a.asset_type)}`,`${b('← Evidencija','back-assets')}${b('Štampa kartice','print-card')}${canWrite()?b('Uredi','edit',`data-table="assets" data-id="${a.id}"`,'primary'):''}`)+`<div class="tabs">${tabs.map(([id,text])=>`<button class="tab ${state.tab===id?'active':''}" data-action="asset-tab" data-tab="${id}">${text}${D[id]?` (${D[id].filter(x=>x.asset_id===a.id).length})`:''}</button>`).join('')}</div>${content}<div class="row">${canWrite()&&a.portfolio_status!=='archived'?b('Arhiviraj nepokretnost','archive',`data-id="${a.id}"`,'quiet'):''}${isAdmin()?b('Trajno obriši','delete',`data-table="assets" data-id="${a.id}"`,'danger small'):''}</div>`);
}
function actionCards(rows){return rows.map(x=>`<article class="step-card ${closed(D,'action_status',x.status)?'closed':''}"><span class="count-dot">${x.position}</span><div class="content"><div class="row between"><h3>${esc(x.description)}</h3>${badge(lbl(D,'action_status',x.status),closed(D,'action_status',x.status)?'green':late(D,x,'due_date','action_status')?'red':'blue')}</div><div class="small muted">${esc(x.responsible||'Odgovorno lice nije uneto')} · Rok: ${date(x.due_date)}</div>${x.notes?`<p class="preline">${esc(x.notes)}</p>`:''}</div>${canWrite()?b('Uredi','edit',`data-table="actions" data-id="${x.id}"`,'small'):''}</article>`).join('');}
const COLUMNS={
 owners:[['code','ID'],['full_name','Vlasnik'],['kind','Tip'],['country','Država'],['within_group','U grupi'],['active','Aktivan']],
 ownerships:[['asset_id','Nepokretnost'],['owner_id','Vlasnik'],['fraction','Udeo'],['acquired_on','Sticanje'],['acquisition_document','Isprava']],
 actions:[['asset_id','Nepokretnost'],['position','Korak'],['description','Opis'],['responsible','Odgovorno lice'],['due_date','Rok'],['status','Status']],
 cases:[['asset_id','Nepokretnost'],['system','Sistem'],['case_number','Broj predmeta'],['case_type','Vrsta'],['status','Faza'],['external_status','Status iz izvora'],['checked_on','Provereno'],['deadline','Rok']],
 documents:[['code','ID'],['asset_id','Nepokretnost'],['title','Dokument'],['document_type','Vrsta'],['status','Status'],['expires_on','Rok'],['file','Datoteka / link']],
 utilities:[['asset_id','Nepokretnost'],['utility_type','Usluga'],['supplier','Dobavljač'],['customer_code','ED / korisnički broj'],['meter_number','Broj brojila'],['power_kw','Snaga (kW)'],['monthly_cost','Mesečni trošak']]
};
function dueTone(r,key,kind){if(late(D,r,key,kind))return 'red';if(!r[key]||(kind&&closed(D,kind,r.status)))return '';const n=Math.round((new Date(r[key]+'T12:00:00Z')-new Date(today()+'T12:00:00Z'))/86400000);return n>=0&&n<=state.org.warning_days?'amber':'';}
function entityCell(t,r,k){if(k==='asset_id')return `<button class="link-btn" data-action="asset" data-id="${r.asset_id}">${esc(assetName(r.asset_id))}</button><div class="subline mono">${esc(assetCode(r.asset_id))}</div>`;if(k==='owner_id')return esc(ownerName(r.owner_id));if(k==='fraction')return `${r.numerator}/${r.denominator}<div class="subline">${percent(r.numerator/r.denominator)}</div>`;if(k==='file')return r.storage_path?b('Preuzmi','file',`data-id="${r.id}"`,'small'):r.url?link(r.url,'Otvori'):'—';if(k==='monthly_cost')return money(r[k],r.currency);if(k==='status'){const kind=t==='actions'?'action_status':t==='cases'?'case_status':'document_status';return badge(lbl(D,kind,r[k]),closed(D,kind,r[k])?'green':r[k]==='missing'?'red':'blue');}if(['due_date','deadline','expires_on'].includes(k)){const kind=t==='actions'?'action_status':t==='cases'?'case_status':null;return badge(date(r[k]),dueTone(r,k,kind));}const f=FIELDS[t].find(f=>f[0]===k);return f?displayField(f,r[k]):esc(r[k]??'—');}
function entityTable(t,rows,paginated=true){const q=norm(state.q);const filtered=rows.filter(r=>!q||norm(Object.values(r).filter(v=>typeof v==='string').join(' ')+' '+assetName(r.asset_id)+' '+ownerName(r.owner_id)).includes(q));const show=paginated?filtered.slice((state.page-1)*25,state.page*25):filtered;return filtered.length?`<div class="table-wrap"><table><thead><tr>${COLUMNS[t].map(([,s])=>`<th>${s}</th>`).join('')}<th></th></tr></thead><tbody>${show.map(r=>`<tr>${COLUMNS[t].map(([k])=>`<td>${entityCell(t,r,k)}</td>`).join('')}<td class="nowrap">${b('Detalji','view',`data-table="${t}" data-id="${r.id}"`,'small quiet')} ${canWrite()?b('Uredi','edit',`data-table="${t}" data-id="${r.id}"`,'small'):'—'} ${isAdmin()?b('Obriši','delete',`data-table="${t}" data-id="${r.id}"`,'small quiet'):''}</td></tr>`).join('')}</tbody></table></div>${paginated?pager(filtered.length):''}`:noData('Nema stavki za prikaz.');}
function renderEntities(t){if(!FIELDS[t]){nav('dashboard');return;}const intro={cases:'Više predmeta po nepokretnosti. CEOP i katastar se vode odvojeno.',actions:'Do pet koraka po nepokretnosti, sa odgovornim licem i rokom.',owners:'Pravna i fizička lica. Oznaka obuhvata određuje čiji se udeli računaju u Balkan grupu.',ownerships:'Jedan zapis po vlasniku i nepokretnosti. Unesite i spoljne suvlasnike.',documents:'Isprave, rokovi provere i privatno čuvanje datoteka.',utilities:'Brojila, korisnički brojevi, ugovori i priključne snage.'};shell(heading(TITLES[t],intro[t],`${b('CSV / Excel','export',`data-table="${t}"`)}${canWrite()?b('+ Dodaj','new',`data-table="${t}"`,'primary'):''}`)+`<div class="toolbar"><div class="search"><input data-search="entity" aria-label="Pretraga stavki" type="search" placeholder="Pretraži podatke…" value="${esc(state.q)}"></div></div>${t==='cases'?`<div class="notice">Ručno ažuriranje statusa. Zvanični portali: ${link('https://www.apr.gov.rs/usluge/eservisi/egradjevinske-dozvole.2407.html','APR / CEOP')} · ${link('https://www.rgz.gov.rs/info-centar-rgz','RGZ / katastar')}.</div>`:''}<section class="panel"><div id="entity-results">${entityTable(t,D[t])}</div></section>`);}
function defaults(t){const nextCode=(prefix,rows)=>prefix+'-'+String(Math.max(0,...rows.map(x=>Number(x.code?.split('-').at(-1))||0))+1).padStart(3,'0');return ({assets:{code:nextCode('NEK',D.assets),country:'RS',portfolio_status:'portfolio',occupancy_permit:'unknown',priority:'medium',reviewed_on:today()},owners:{code:nextCode('VLA',D.owners),country:'RS',kind:'legal',within_group:true,active:true},ownerships:{asset_id:state.asset??'',numerator:1,denominator:1},actions:{asset_id:state.asset??'',position:state.asset?[1,2,3,4,5].find(p=>!D.actions.some(x=>x.asset_id===state.asset&&x.position===p))??1:1,status:'not_started'},cases:{asset_id:state.asset??'',system:'ceop',status:'submitted',checked_on:today()},documents:{code:nextCode('DOC',D.documents),asset_id:state.asset??'',status:'exists'},utilities:{asset_id:state.asset??''}})[t]??{};}
function inputField(f,r){const [k,text,type,,required,kind]=f;const value=r[k]??'';let input='';const attrs=`id="f-${k}" name="${k}" ${required?'required':''}`;if(type==='select')input=`<select ${attrs}>${options(kind,value,'Izaberite…')}</select>`;else if(type==='owner')input=`<select ${attrs}>${optionTag('','Izaberite vlasnika…',value)}${D.owners.filter(x=>x.active||x.id===value).sort((a,b)=>a.full_name.localeCompare(b.full_name,'sr')).map(x=>optionTag(x.id,x.code+' · '+x.full_name,value)).join('')}</select>`;else if(type==='asset')input=`<select ${attrs}>${optionTag('','Izaberite nepokretnost…',value)}${D.assets.sort((a,b)=>a.code.localeCompare(b.code,'sr')).map(x=>optionTag(x.id,x.code+' · '+x.name,value)).join('')}</select>`;else if(type==='currency')input=`<select ${attrs}>${optionTag('','Izaberite…',value)}${['EUR','RSD'].map(x=>optionTag(x,x,value)).join('')}</select>`;else if(type==='owner_kind')input=`<select ${attrs}>${optionTag('legal','Pravno lice',value)}${optionTag('natural','Fizičko lice',value)}</select>`;else if(type==='case_system')input=`<select ${attrs}>${[['ceop','CEOP'],['cadastre','Katastar nepokretnosti'],['other','Drugo']].map(([v,s])=>optionTag(v,s,value)).join('')}</select>`;else if(type==='position')input=`<select ${attrs}>${[1,2,3,4,5].map(x=>optionTag(x,'Korak '+x,value)).join('')}</select>`;else if(type==='checkbox')input=`<label class="check-label"><input type="checkbox" ${attrs} ${value?'checked':''}>${esc(text)}</label>`;else if(type==='textarea')input=`<textarea ${attrs} maxlength="20000" rows="4">${esc(value)}</textarea>`;else if(type==='file')input=`<input type="file" ${attrs} accept=".pdf,.jpg,.jpeg,.png,.webp,.docx,.xlsx,.txt">${r.file_name?`<div class="subline">Trenutna datoteka: ${esc(r.file_name)}. Novi prilog je zamenjuje.</div>`:''}${state.demo?'<div class="subline">U demo režimu koristite spoljni link. Upload je dostupan uz povezanu bazu.</div>':''}`;else input=`<input ${attrs} type="${['number','integer'].includes(type)?'number':type}" ${['number','integer'].includes(type)?`min="${type==='integer'?1:0}" max="${type==='integer'?1000000000:1000000000000}" step="${type==='integer'?1:'0.01'}"`:'maxlength="1000"'} value="${esc(value)}">`;return `<div class="field ${['textarea','file'].includes(type)?'wide':''}">${type==='checkbox'?'':`<label for="f-${k}">${esc(text)}${required?' *':''}</label>`}${input}</div>`;}
function openEditor(t,id){if(!canWrite())return;if(t!=='owners'&&t!=='assets'&&!D.assets.length){toast('Prvo unesite nepokretnost.',true);return;}if(t==='ownerships'&&!D.owners.length){toast('Prvo unesite vlasnika.',true);return;}const existing=id?D[t].find(x=>x.id===id):null;modal={table:t,existing,record:{...defaults(t),...existing},group:FIELDS[t][0][3]};focusBeforeModal=document.activeElement;dirty=false;const groups=[...new Set(FIELDS[t].map(f=>f[3]))];$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${existing?'Uredi':'Dodaj'} · ${TITLES[t]}</h2>${b('×','close-modal','','quiet')}</div><div class="modal-body"><div id="form-error" class="form-error hidden" role="alert"></div>${groups.length>1?`<div class="tabs">${groups.map((g,i)=>`<button type="button" class="tab ${i===0?'active':''}" data-action="form-tab" data-group="${esc(g)}">${esc(g)}</button>`).join('')}</div>`:''}<form id="record-form" novalidate>${groups.map((g,i)=>`<div class="form-grid ${i===0?'':'hidden'}" data-form-group="${esc(g)}">${FIELDS[t].filter(f=>f[3]===g).map(f=>inputField(f,modal.record)).join('')}</div>`).join('')}</form>${t==='assets'?'<p class="small muted">Vlasnički udeli, pet koraka, predmeti, dokumenti i komunalije dodaju se zasebno na kartici nepokretnosti.</p>':''}${t==='cases'?'<p class="small muted">Faza postupka služi za izveštaje. U „Status iz izvora“ prepišite tačan status iz CEOP-a ili katastra.</p>':''}</div><div class="modal-footer"><span id="draft-flag" class="draft-flag"></span>${b('Otkaži','close-modal')}<button type="submit" form="record-form" class="btn primary" id="save-button">Sačuvaj</button></div></section></div>`;setTimeout(()=>$('#record-form input,#record-form select')?.focus(),0);}
function setFormTab(group){modal.group=group;$$('[data-form-group]').forEach(x=>x.classList.toggle('hidden',x.dataset.formGroup!==group));$$('[data-action="form-tab"]').forEach(x=>x.classList.toggle('active',x.dataset.group===group));}
function closeModal(force=false){if(savingRecord&&!force){toast('Sačekajte završetak čuvanja.');return;}if(!force&&dirty&&!confirm('Odbaciti nesačuvane izmene?'))return;$('#modal-root').innerHTML='';modal=null;dirty=false;focusBeforeModal?.focus?.();}
function formError(e){const el=$('#form-error');if(el){el.textContent=friendly(e);el.classList.remove('hidden');el.scrollIntoView({block:'nearest'});}else toast(friendly(e),true);}
function collectRecord(){const r={};for(const f of FIELDS[modal.table]){const [k,text,type,group,required]=f;const el=$('#f-'+k);if(type==='file')continue;let value=type==='checkbox'?el.checked:el.value.trim();if(required&&(value===''||value===null)){setFormTab(group);el.focus();throw new Error('Popunite obavezno polje: '+text);}if(!el.checkValidity()){setFormTab(group);el.reportValidity();throw new Error('Proverite polje: '+text);}if(value==='')value=null;else if(['number','integer','position'].includes(type))value=Number(value);r[k]=value;}validate(modal.table,r,D,modal.existing?.id);return r;}
async function submitRecord(){const button=$('#save-button');let uploaded=null;try{const r=collectRecord(),t=modal.table,existing=modal.existing;const file=$('#f-upload')?.files?.[0];if(file&&state.demo)throw new Error('Upload datoteka je dostupan nakon povezivanja sa Supabase-om. Za demo unesite spoljni link.');button.disabled=true;savingRecord=true;$$('#record-form input,#record-form select,#record-form textarea').forEach(x=>x.disabled=true);button.textContent='Čuvanje…';if(file){const mimes={pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',txt:'text/plain'};const ext=file.name.split('.').pop().toLowerCase();if(!mimes[ext]||file.size>20971520)throw new Error('Dozvoljeni su PDF, JPG, PNG, WEBP, DOCX, XLSX i TXT do 20 MB.');uploaded=`${state.profile.org_id}/${r.asset_id}/${uid()}/${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await client.storage.from(BUCKET).upload(uploaded,file,{contentType:mimes[ext],upsert:false});if(error){uploaded=null;throw error;}Object.assign(r,{storage_path:uploaded,file_name:file.name,mime_type:mimes[ext],file_size:file.size});}else if(t==='documents'&&existing?.storage_path&&r.asset_id!==existing.asset_id){throw new Error('Dokument sa priloženom datotekom pripada postojećoj nepokretnosti. Za premeštanje priložite novu datoteku.');}const saved=await saveRecord(t,r,existing);const committedUpload=uploaded;uploaded=null;if(t==='documents'&&committedUpload&&existing?.storage_path){try{const {error}=await client.storage.from(BUCKET).remove([existing.storage_path]);if(error)throw error;}catch{toast('Nova datoteka je sačuvana. Administrator treba da ukloni prethodnu datoteku iz Storage-a.',true);}}closeModal(true);if(t==='assets'){state.asset=saved.id;state.route='assets';state.tab='overview';}render();toast('Podaci su sačuvani.');}catch(e){if(uploaded){const {error}=await client.storage.from(BUCKET).remove([uploaded]);if(error)toast('Neuspešno čuvanje zapisa. Administrator treba da proveri nepotvrđenu datoteku u Storage-u.',true);}formError(e);}finally{savingRecord=false;$$('#record-form input,#record-form select,#record-form textarea').forEach(x=>x.disabled=false);if(button?.isConnected){button.disabled=false;button.textContent='Sačuvaj';}}}
function reportTable(headers,rows){return rows.length?`<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p class="muted">Nema podataka za izabrane kriterijume.</p>';}
function reportFrame(title,body,scope=''){return `<article class="report-paper"><div class="small strong">${esc(state.org.name.toUpperCase())}${state.demo?' · DEMO PODACI':''}</div><h2>${esc(title)}</h2><div class="report-meta">Datum: ${date(today())} · ${esc(scope||'Pregled evidencije nepokretnosti')}</div>${body}<div class="print-note footer-note">Izvor: interna evidencija Balkan Imovina. CEOP i katastarski statusi ažuriraju se ručno prema datumu poslednje provere.</div></article>`;}
function filterDescription(){const f=state.filters;return [f.owner?'Vlasnik: '+ownerName(f.owner):'',f.city?'Grad: '+f.city:'',f.asset_type?'Vrsta: '+lbl(D,'asset_type',f.asset_type):'',f.portfolio_status?'Status: '+lbl(D,'portfolio_status',f.portfolio_status):'',f.occupancy_permit?'Upotrebna: '+lbl(D,'permit_status',f.occupancy_permit):'',f.q?'Pretraga: '+f.q:''].filter(Boolean).join(' · ');}
function reportData(type=state.report){let f={...state.filters};if(type==='progress')f.mode='progress';if(type==='no_permit')f.mode='no_permit';const assets=filterAssets(D,f).sort((a,b)=>a.code.localeCompare(b.code,'sr')),ids=new Set(assets.map(a=>a.id));
 if(type==='owners'){const heads=['Vlasnik','Tip','Nepokretnosti','Vrednost udela EUR','Vrednost udela RSD','Nepotpuni udeli'];const rows=D.owners.filter(o=>!f.owner||o.id===f.owner).map(o=>{const own=D.ownerships.filter(x=>x.owner_id===o.id&&ids.has(x.asset_id));let eur=0,rsd=0,missing=0;for(const x of own){const a=assets.find(a=>a.id===x.asset_id);if(!shares(D,a.id).complete||a.market_value==null||!a.currency){missing++;continue;}const value=a.market_value*x.numerator/x.denominator;if(a.currency==='EUR')eur+=value;else rsd+=value;}return [o.full_name,o.kind==='legal'?'Pravno lice':'Fizičko lice',new Set(own.map(x=>x.asset_id)).size,eur,rsd,missing];});return {title:'Izveštaj po firmi / vlasniku',heads,rows,html:reportTable(heads,rows.map(r=>r.map((v,i)=>i===3||i===4?number(v):esc(v))))+'<p class="small muted">Vrednost predstavlja procenjeni pripadajući udeo vlasnika. Nepotpuni vlasnički udeli i nepokretnosti bez procene ili valute nisu uključeni u iznose.</p>'};}
 if(['cases','actions','documents'].includes(type)){const definitions={cases:{title:'Pregled otvorenih CEOP i katastarskih predmeta',heads:['Nepokretnost','Grad','Sistem','Broj predmeta','Faza / status iz izvora','Provereno','Rok'],rows:D.cases.filter(x=>ids.has(x.asset_id)&&!closed(D,'case_status',x.status)).map(x=>[assetCode(x.asset_id)+' · '+assetName(x.asset_id),D.assets.find(a=>a.id===x.asset_id)?.city,({ceop:'CEOP',cadastre:'Katastar',other:'Drugo'})[x.system],x.case_number,lbl(D,'case_status',x.status)+(x.external_status?' / '+x.external_status:''),date(x.checked_on),date(x.deadline)])},actions:{title:'Pregled otvorenih koraka',heads:['Nepokretnost','Korak','Opis','Odgovorno lice','Rok','Status'],rows:D.actions.filter(x=>ids.has(x.asset_id)&&!closed(D,'action_status',x.status)).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).map(x=>[assetCode(x.asset_id)+' · '+assetName(x.asset_id),x.position,x.description,x.responsible,date(x.due_date),lbl(D,'action_status',x.status)])},documents:{title:'Dokumentacija i rokovi',heads:['Nepokretnost','Dokument','Vrsta','Status','Broj','Rok'],rows:D.documents.filter(x=>ids.has(x.asset_id)).map(x=>[assetCode(x.asset_id)+' · '+assetName(x.asset_id),x.title,lbl(D,'document_type',x.document_type),lbl(D,'document_status',x.status),x.document_number,date(x.expires_on)])}};const r=definitions[type];return {...r,html:reportTable(r.heads,r.rows.map(row=>row.map(esc)))};}
 const heads=['ID / nepokretnost','Grad / KO / parcela','Vlasnici','Vrsta','Status','Upotrebna dozvola','Naredni korak / rok'];const rows=assets.map(a=>{const next=openSteps(D,a.id)[0];return [a.code+' · '+a.name,[a.city,a.cadastral_municipality?'KO '+a.cadastral_municipality:'',a.parcel_number?'Parcela '+a.parcel_number:''].filter(Boolean).join(' / '),shares(D,a.id).rows.map(x=>ownerName(x.owner_id)+' '+x.numerator+'/'+x.denominator).join('; ')||ownerName(a.lead_owner_id),lbl(D,'asset_type',a.asset_type),lbl(D,'portfolio_status',a.portfolio_status),lbl(D,'permit_status',a.occupancy_permit),next?next.description+' / '+date(next.due_date):'—'];});const title=type==='progress'?'Nepokretnosti u postupku':type==='no_permit'?'Nepokretnosti bez upotrebne dozvole':'Pregled nepokretnosti';const financial=totals(D,assets);return {title,heads,rows,html:`<p class="small">Ukupno: <b>${countNoun(assets.length,'nepokretnost','nepokretnosti','nepokretnosti')}</b>.</p>`+reportTable(heads,rows.map(row=>row.map(esc)))+'<div class="report-title">Zbir unetih vrednosti izabranih nepokretnosti</div>'+reportTable(['Valuta','Tržišna vrednost 100%','Vrednost udela grupe','Zakup mesečno 100%','Procene sa nepotpunim udelima'],financial.map(x=>[esc(x.currency),number(x.market),number(x.group),number(x.rent),x.missingShares]))+'<p class="small muted">Vrednosti se odnose na 100% jedinstvenih nepokretnosti, bez dupliranja po suvlasnicima. Za pripadajuće vrednosti po vlasniku koristite izveštaj „Po firmi / vlasniku“. Prazni finansijski podaci nisu procenjeni kao nula pojedinačne nepokretnosti.</p>'};
}
function renderReports(){const r=reportData();shell(heading('Izveštaji','Izaberite vrstu pregleda i kombinujte filtere. Izveštaj možete odštampati ili sačuvati kao PDF.',`${b('CSV / Excel','report-csv')}${b('Štampa / PDF','print-report','','primary')}`)+`<section class="panel"><div class="panel-body"><label for="report-type">Vrsta izveštaja</label><select id="report-type">${[['holdings','Pregled nepokretnosti'],['owners','Po firmi / vlasniku'],['progress','Nepokretnosti u postupku'],['no_permit','Bez upotrebne dozvole'],['cases','Otvoreni CEOP / katastarski predmeti'],['actions','Otvoreni koraci i rokovi'],['documents','Dokumentacija i rokovi']].map(([v,s])=>optionTag(v,s,state.report)).join('')}</select></div>${filterPanel()}</section>${reportFrame(r.title,r.html,filterDescription())}`);}
function cardReport(a){const share=shares(D,a.id);let html='';for(const group of ['Osnovno','Katastar i dozvole','Finansije']){html+=`<div class="report-title">${group}</div><div class="report-kv">${FIELDS.assets.filter(f=>f[3]===group).map(f=>`<div><b>${esc(f[1])}</b>${displayField(f,a[f[0]])}</div>`).join('')}</div>`;}html+='<div class="report-title">Vlasništvo i udeli</div>'+reportTable(['Vlasnik','Udeo','Udeo %','U grupi'],share.rows.map(x=>[esc(ownerName(x.owner_id)),`${x.numerator}/${x.denominator}`,percent(x.numerator/x.denominator),D.owners.find(o=>o.id===x.owner_id)?.within_group?'Da':'Ne']));html+=`<p class="small">Evidentirano: ${percent(share.total)}. Udeo grupe: ${percent(share.group)}. ${share.complete?'':'Vlasnički udeli nisu potpuno evidentirani.'}</p>`;
 html+='<div class="report-title">Pet narednih koraka</div>'+reportTable(['Korak','Opis','Odgovorno lice','Rok','Status'],steps(D,a.id).map(x=>[x.position,esc(x.description),esc(x.responsible),date(x.due_date),esc(lbl(D,'action_status',x.status))]));
 html+='<div class="report-title">CEOP i katastar</div>'+reportTable(['Sistem / broj predmeta','Vrsta','Faza / tačan status','Provereno','Rok'],D.cases.filter(x=>x.asset_id===a.id).map(x=>[esc((x.system==='ceop'?'CEOP':x.system==='cadastre'?'Katastar':'Drugo')+' / '+x.case_number),esc(lbl(D,'case_type',x.case_type)),esc(lbl(D,'case_status',x.status)+(x.external_status?' / '+x.external_status:'')),date(x.checked_on),date(x.deadline)]));
 html+='<div class="report-title">Dokumentacija</div>'+reportTable(['Dokument','Broj','Status','Rok','Datoteka'],D.documents.filter(x=>x.asset_id===a.id).map(x=>[esc(x.title),esc(x.document_number),esc(lbl(D,'document_status',x.status)),date(x.expires_on),esc(x.file_name||x.url||'—')]));
 html+='<div class="report-title">Komunalije i priključci</div>'+reportTable(['Usluga / dobavljač','Korisnički broj','Brojilo','Snaga kW','Mesečni trošak'],D.utilities.filter(x=>x.asset_id===a.id).map(x=>[esc(lbl(D,'utility_type',x.utility_type)+' / '+(x.supplier||'—')),esc(x.customer_code),esc(x.meter_number),number(x.power_kw),money(x.monthly_cost,x.currency)]));
 html+=`<div class="report-title">Napomena – slobodan unos</div><div class="preline">${esc(a.notes||'Nema napomene.')}</div><p class="small muted">Datum poslednje provere: ${date(a.reviewed_on)}<br>Svi finansijski iznosi su u valuti ${esc(a.currency||'koja nije uneta')} i odnose se na 100% nepokretnosti.</p>`;return reportFrame('Kartica nepokretnosti: '+a.name,html,a.code+' · '+a.city);
}

function showPrintPreview(html,landscape=true){simpleModal('Pregled za štampu',html,b('Preuzmi dokument za štampu','print-download')+b('Štampa / PDF','print-confirm','','primary'),false);modal.printDocument=html;modal.landscape=landscape;}
function standalonePrintDocument(html,landscape){const css=document.querySelector('head style').textContent;return '<!doctype html><html lang="sr-Latn"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src '+"'none'; style-src 'unsafe-inline'; img-src data:"+'"><title>Balkan Imovina — dokument za štampu</title><style>'+css+'\nbody{background:white;margin:20px auto;max-width:1200px}#print-root{display:block!important}@media print{@page{size:A4 '+(landscape?'landscape':'portrait')+';margin:13mm}}</style><body><main id="print-root">'+html+'</main></bo'+'dy></html>';}

function printHtml(html,landscape=true){$('#print-root').innerHTML=html;let style=$('#print-orientation');if(!style){style=document.createElement('style');style.id='print-orientation';document.head.append(style);}style.textContent=`@media print{@page{size:A4 ${landscape?'landscape':'portrait'};margin:13mm}}`;window.print();}
function exportEntity(t){let rows=t==='assets'?filterAssets(D,state.filters):D[t];if(state.q&&t!=='assets')rows=rows.filter(r=>norm(JSON.stringify(r)+' '+assetName(r.asset_id)+' '+ownerName(r.owner_id)).includes(norm(state.q)));const fields=FIELDS[t].filter(f=>f[2]!=='file');const value=(r,f)=>{const v=r[f[0]],type=f[2];if(v==null)return '';if(type==='select')return lbl(D,f[5],v);if(type==='owner')return ownerName(v);if(type==='asset')return assetCode(v);if(type==='checkbox')return v?'Da':'Ne';if(type==='owner_kind')return v==='legal'?'Pravno lice':'Fizičko lice';return v;};const headers=fields.map(f=>f[1]);if(t==='assets')headers.push('Celokupan evidentirani udeo','Udeo grupe','Vrednost udela grupe','Naredni korak','Rok narednog koraka');const matrix=[headers,...rows.map(r=>{const result=fields.map(f=>value(r,f));if(t==='assets'){const s=shares(D,r.id),next=openSteps(D,r.id)[0];result.push(s.total,s.group,s.complete&&r.market_value!=null?r.market_value*s.group:null,next?.description,next?.due_date);}return result;})];download(`Balkan_${t}_${today()}.csv`,csv(matrix),'text/csv;charset=utf-8');}
async function loadAudit(){if(state.demo)return;const {data,error}=await client.from('bg_audit_log').select('*').eq('org_id',state.profile.org_id).order('created_at',{ascending:false}).limit(200);if(error)throw error;D.audit_log=data;}
function renderAdmin(){if(!isAdmin()){nav('dashboard');return;}let html='';if(state.adminTab==='options'){const opts=D.options.filter(o=>o.kind===state.category).sort((a,b)=>a.sort_order-b.sort_order);html=`<section class="panel"><div class="panel-head"><h2>Liste i statusi</h2>${b('+ Nova stavka','new-option','','primary')}</div><div class="panel-body"><label for="option-category">Kategorija</label><select id="option-category">${Object.entries(CATEGORY_LABELS).map(([k,s])=>optionTag(k,s,state.category)).join('')}</select><p class="small muted">Nazivi se mogu menjati. Trajne šifre čuvaju ispravnost postojećih podataka i izveštaja. Neaktivna stavka ostaje na postojećim zapisima.</p></div><div class="table-wrap"><table><thead><tr><th>Naziv</th><th>Redosled</th><th>Aktivno</th><th>Pravila izveštaja</th><th></th></tr></thead><tbody>${opts.map(o=>`<tr><td>${esc(o.label)}</td><td>${o.sort_order}</td><td>${badge(o.active?'Da':'Ne',o.active?'green':'')}</td><td>${o.flags?.portfolio?'U portfelju ':''}${o.flags?.closed?'Zatvara korak / predmet ':''}${o.flags?.in_progress?'Postupak u toku':''}</td><td>${b('Uredi','edit-option',`data-id="${o.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section>`;}else if(state.adminTab==='users'){html=`<div class="notice">Nalog prvo kreirajte ili pozovite kroz ${currentConfig?link('https://supabase.com/dashboard/project/'+new URL(currentConfig.url).hostname.split('.')[0]+'/auth/users','Supabase Authentication'):'Supabase Authentication'}. Novi korisnik je neaktivan dok mu ovde ne dodelite pristup. Pregled čita podatke, Urednik ih unosi i menja, Administrator upravlja pristupom i brisanjem.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Korisnik</th><th>E-mail</th><th>Uloga</th><th>Aktivan</th><th></th></tr></thead><tbody>${(state.demo?[state.profile]:D.profiles).map(p=>`<tr><td>${esc(p.display_name)}</td><td>${esc(p.email||'DEMO')}</td><td>${esc(p.role)}</td><td>${p.active?'Da':'Ne'}</td><td>${b('Uredi pristup','edit-user',`data-id="${p.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section>`;}else if(state.adminTab==='audit'){html=`<section class="panel"><div class="panel-head"><h2>Poslednjih 200 izmena</h2>${b('Osveži istoriju','audit-refresh','','small')}</div><div class="table-wrap"><table><thead><tr><th>Datum</th><th>Korisnik</th><th>Tabela</th><th>Radnja</th><th></th></tr></thead><tbody>${D.audit_log.map(x=>`<tr><td>${date(x.created_at)} ${new Date(x.created_at).toLocaleTimeString('sr-Latn-RS',{timeZone:'Europe/Belgrade',hour:'2-digit',minute:'2-digit'})}</td><td>${esc(x.actor_name||'Sistem')}</td><td>${esc(TITLES[x.entity?.replace('bg_','')]||x.entity)}</td><td>${esc(x.operation)}</td><td>${b('Detalji','audit-detail',`data-id="${x.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section>`;}else{html=`<section class="panel"><div class="panel-head"><h2>Podešavanja evidencije</h2></div><div class="panel-body"><form id="org-form" class="form-grid"><div><label for="org-name">Naziv grupe</label><input id="org-name" required value="${esc(state.org.name)}" maxlength="120"></div><div><label for="org-days">Najava rokova (dana)</label><input id="org-days" type="number" required min="0" max="365" step="1" value="${state.org.warning_days}"></div><div class="wide"><button class="btn primary" type="submit">Sačuvaj podešavanja</button></div></form><div class="hr"></div><h3>Izvoz podataka i instalacija</h3><div class="row">${b('Izvezi JSON rezervnu kopiju','backup')}${b('Preuzmi SQL za bazu','download-sql')}${b('Uputstvo','help')}</div><p class="small muted">JSON sadrži podatke i metapodatke priloga. Same datoteke se čuvaju zasebno u Supabase Storage-u. Kopija sadrži poslovne i lične podatke i namenjena je ovlašćenim licima.</p></div></section>`;}shell(heading('Administracija','Vlasnici, statusi, korisnička prava i evidencija izmena.')+`<div class="tabs">${[['options','Liste i statusi'],['users','Korisnici'],['audit','Istorija izmena'],['settings','Podešavanja']].map(([id,s])=>`<button class="tab ${state.adminTab===id?'active':''}" data-action="admin-tab" data-tab="${id}">${s}</button>`).join('')}</div>${html}`);}
function simpleModal(title,body,footer='',small=true){focusBeforeModal=document.activeElement;modal={custom:true};dirty=false;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${small?'small-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${b('×','close-modal','','quiet')}</div><div class="modal-body"><div id="form-error" class="form-error hidden" role="alert"></div>${body}</div><div class="modal-footer">${b('Zatvori','close-modal')}${footer}</div></section></div>`;}
function editOption(id){const old=D.options.find(o=>o.id===id);const r=old??{kind:state.category,label:'',sort_order:0,active:true,flags:{}};simpleModal(old?'Uredi stavku liste':'Nova stavka liste',`<form id="option-form" class="form-grid"><div class="wide"><label for="option-label">Naziv</label><input id="option-label" required maxlength="120" value="${esc(r.label)}"></div><div><label for="option-sort">Redosled</label><input id="option-sort" type="number" min="0" max="10000" step="1" value="${r.sort_order}"></div><label class="check-label"><input id="option-active" type="checkbox" ${r.active?'checked':''}>Aktivna stavka</label>${r.kind==='portfolio_status'?`<label class="check-label wide"><input id="option-portfolio" type="checkbox" ${r.flags.portfolio?'checked':''}>Uključiti u vrednost portfelja</label>`:''}${['action_status','case_status'].includes(r.kind)?`<label class="check-label wide"><input id="option-closed" type="checkbox" ${r.flags.closed?'checked':''}>Ovaj status zatvara korak / predmet</label>`:''}${r.kind==='proceedings_status'?`<label class="check-label wide"><input id="option-progress" type="checkbox" ${r.flags.in_progress?'checked':''}>Prikazuje se u izveštaju „U postupku“</label>`:''}</form>`,`<button class="btn primary" type="submit" form="option-form">Sačuvaj</button>`);modal.option=old;modal.optionKind=r.kind;}
function editUser(id){const p=(state.demo?[state.profile]:D.profiles).find(p=>p.id===id);simpleModal('Pristup korisnika',`<form id="user-form" class="form-grid"><div class="wide"><label for="user-name">Ime za prikaz</label><input id="user-name" maxlength="120" value="${esc(p.display_name)}"></div><div><label for="user-role">Uloga</label><select id="user-role">${[['admin','Administrator'],['editor','Urednik'],['viewer','Pregled']].map(([v,s])=>optionTag(v,s,p.role)).join('')}</select></div><label class="check-label"><input id="user-active" type="checkbox" ${p.active?'checked':''}>Aktivan pristup</label></form>`,`<button class="btn primary" type="submit" form="user-form">Sačuvaj</button>`);modal.profile=p;}
function account(){simpleModal('Moj nalog',state.demo?`<p>Demo uloga služi za proveru prikaza i dostupnih radnji.</p><label for="demo-role">Uloga u demonstraciji</label><select id="demo-role">${[['admin','Administrator'],['editor','Urednik'],['viewer','Pregled']].map(([v,s])=>optionTag(v,s,state.profile.role)).join('')}</select><div class="hr"></div>${b('Vrati početne demo podatke','reset-demo','','danger')}`:`<p class="small muted">${esc(state.profile.email)}</p><form id="password-form"><div class="field"><label for="new-password">Nova lozinka (najmanje 12 znakova)</label><input id="new-password" type="password" autocomplete="new-password" minlength="12" required></div><div class="field"><label for="confirm-password">Ponovite lozinku</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="12" required></div><button type="submit" class="btn primary">Promeni lozinku</button></form>`);}
function help(){simpleModal('Pokretanje i korišćenje',`<ol class="info-list"><li>U Supabase SQL Editor-u pokrenite priloženi <b>schema.sql</b>. Kreirajte prvog korisnika u Authentication i dodelite mu admin ulogu komandom na kraju SQL fajla.</li><li>U Supabase Auth podesite Site URL i dozvoljene Redirect URLs na stvarnu HTTPS adresu aplikacije. Isključite javno prijavljivanje novih naloga i podesite produkcijski SMTP za pozivnice i obnovu lozinke.</li><li>Za Vercel postavite promenljive <b>SUPABASE_URL</b> i <b>SUPABASE_PUBLISHABLE_KEY</b>. Build komanda je <b>node build.mjs</b>, izlazni direktorijum <b>public</b>.</li><li>Prvo unesite vlasnike, zatim nepokretnosti i suvlasničke udele. Na kartici nepokretnosti dodajte korake, predmete, dokumente i komunalije.</li><li>U izveštajima se valute ne mešaju i nepokretnosti se ne dupliraju po suvlasnicima. Statusi CEOP-a i katastra unose se ručno.</li><li>Posle povezivanja proverite prijavu, sva tri nivoa pristupa, upload/preuzimanje priloga i štampu. Bez ove provere konkretna instalacija još nije potvrđena za rad.</li></ol><div class="row">${b('Preuzmi SQL','download-sql')}${b('Preuzmi Vercel konfiguraciju','download-vercel')}</div>`,'',false);}
function renderLogin(showConfig=false){state.profile=null;const configured=!!client&&!showConfig;$('#app').innerHTML=`<div class="login"><section class="login-intro"><div class="brand">BALKAN<small>IMOVINA</small></div><div><h1>Evidencija nepokretnosti</h1><p>Vlasništvo, katastarski podaci, dozvole i postupci. Jedinstvena evidencija za pravna i fizička lica Balkan grupe.</p><div class="login-list"><span>01 · Kartice nepokretnosti i suvlasnički udeli</span><span>02 · CEOP, katastar i naredni koraci</span><span>03 · Dokumentacija i izveštaji za štampu</span></div></div><p class="small">Pristup je omogućen samo odobrenim korisnicima.</p></section><section class="login-form-side"><div class="login-card"><h2>${configured?'Prijava':'Povezivanje evidencije'}</h2><p class="muted small">${configured?'Prijavite se službenim nalogom.':'Unesite javne parametre Supabase projekta ili prvo isprobajte demonstraciju.'}</p><div id="login-error" class="form-error hidden" role="alert"></div>${configured?`<form id="login-form"><div class="field"><label for="login-email">E-mail</label><input id="login-email" type="email" required autocomplete="username"></div><div class="field"><label for="login-password">Lozinka</label><input id="login-password" type="password" required autocomplete="current-password"></div><button class="btn primary full" type="submit">Prijavi se</button></form><div class="row between" style="margin-top:12px">${b('Zaboravljena lozinka','forgot','','quiet small')}${!CONFIG.url?b('Parametri veze','show-config','','quiet small'):''}</div>`:`<form id="config-form"><div class="field"><label for="config-url">Supabase Project URL</label><input id="config-url" type="url" required placeholder="https://projekat.supabase.co" value="${esc(currentConfig?.url||'')}"></div><div class="field"><label for="config-key">Publishable / anon ključ</label><textarea id="config-key" required rows="3" placeholder="sb_publishable_…">${esc(currentConfig?.key||'')}</textarea></div><button type="submit" class="btn primary full">Poveži bazu</button></form><p class="small muted">Koristi se samo javni publishable ključ. Pristup podacima odobrava prijava i pravila baze.</p>`}<div class="divider">Provera pre povezivanja</div>${b('Otvori demo evidenciju','demo','','full')}<div class="row between" style="margin-top:17px">${b('SQL za bazu','download-sql','','small quiet')}${b('Uputstvo','help','','small quiet')}</div><p class="small muted">Verzija ${VERSION} · Demo i produkcijski podaci su odvojeni.</p></div></section></div>`;}
function renderPending(){$('#app').innerHTML=`<div class="login-form-side" style="min-height:100vh"><div class="login-card"><h2>Nalog čeka odobrenje</h2><p class="muted">${esc(state.profile?.email)} nema aktivan pristup evidenciji. Administrator treba da odobri nalog u administraciji.</p>${b('Proveri ponovo','check-access','','primary')} ${b('Odjava','logout')}</div></div>`;}
function renderRecovery(){$('#app').innerHTML=`<div class="login-form-side" style="min-height:100vh"><div class="login-card"><h2>Postavite novu lozinku</h2><p class="muted">Najmanje 12 znakova.</p><div id="login-error" class="form-error hidden"></div><form id="password-form"><div class="field"><label for="new-password">Nova lozinka</label><input id="new-password" type="password" autocomplete="new-password" minlength="12" required></div><div class="field"><label for="confirm-password">Ponovite lozinku</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="12" required></div><button class="btn primary full" type="submit">Sačuvaj lozinku</button></form></div></div>`;}
function loginError(e){const el=$('#login-error');if(el){el.textContent=friendly(e);el.classList.remove('hidden');}else formError(e);}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id,t=el.dataset.table;
 if(a==='nav'){nav(el.dataset.route);return;}if(a==='demo'){enterDemo();return;}if(a==='asset'){goAsset(id,el.dataset.tab||'overview');return;}if(a==='asset-tab'){state.tab=el.dataset.tab;render();return;}if(a==='back-assets'){state.asset=null;state.q='';render();return;}
 if(a==='new'||a==='edit'){openEditor(t,a==='edit'?id:null);return;}if(a==='view'){const r=D[t].find(x=>x.id===id);simpleModal(TITLES[t],detailFields(FIELDS[t],r)+(r.storage_path?'<div class="hr"></div>'+b('Preuzmi prilog','file',`data-id="${id}"`):''),'',false);return;}
 if(a==='close-modal'){closeModal();return;}if(a==='form-tab'){setFormTab(el.dataset.group);return;}if(a==='menu'){$('.sidebar').classList.toggle('open');return;}if(a==='refresh'){el.disabled=true;try{await reload();toast('Podaci su osveženi.');}finally{if(el.isConnected)el.disabled=false;}return;}if(a==='check-access'){await startSession();return;}
 if(a==='quick-filter'){state.route='assets';state.filters={mode:el.dataset.mode};state.page=1;render();return;}if(a==='status-filter'){state.route='assets';state.filters={portfolio_status:el.dataset.status};state.page=1;render();return;}
 if(a==='filters'){state.showFilters=!state.showFilters;render();return;}if(a==='clear-filters'){state.filters={};state.page=1;render();return;}if(a==='page'){state.page+=Number(el.dataset.dir);render();return;}
 if(a==='delete'){await removeRecord(t,id);return;}if(a==='archive'){if(!confirm('Arhivirati nepokretnost? Povezani podaci ostaju u evidenciji.'))return;const old=D.assets.find(x=>x.id===id);await saveRecord('assets',{portfolio_status:'archived'},old);render();toast('Nepokretnost je arhivirana.');return;}
 if(a==='export'){exportEntity(t);return;}if(a==='report-csv'){const r=reportData();download('Balkan_izvestaj_'+today()+'.csv',csv([r.heads,...r.rows]),'text/csv;charset=utf-8');return;}
 if(a==='print-card'){showPrintPreview(cardReport(D.assets.find(x=>x.id===state.asset)),false);return;}if(a==='print-report'||a==='print-list'){const r=reportData(a==='print-list'?'holdings':state.report);showPrintPreview(reportFrame(r.title,r.html,filterDescription()),true);return;}
 if(a==='print-confirm'){if(!modal?.printDocument)return;printHtml(modal.printDocument,modal.landscape);return;}
 if(a==='print-download'){if(!modal?.printDocument)return;download('Balkan_dokument_za_stampu_'+today()+'.html',standalonePrintDocument(modal.printDocument,modal.landscape),'text/html;charset=utf-8');return;}
 if(a==='admin-tab'){state.adminTab=el.dataset.tab;if(state.adminTab==='audit')await loadAudit();render();return;}if(a==='new-option'||a==='edit-option'){editOption(id);return;}if(a==='edit-user'){editUser(id);return;}if(a==='account'){account();return;}if(a==='audit-refresh'){await loadAudit();render();return;}
 if(a==='audit-detail'){const item=D.audit_log.find(x=>String(x.id)===id);simpleModal('Detalji izmene',`<h3>Pre izmene</h3><pre class="preline small">${esc(JSON.stringify(item.old_data,null,2))}</pre><h3>Posle izmene</h3><pre class="preline small">${esc(JSON.stringify(item.new_data,null,2))}</pre>`,'',false);return;}
 if(a==='backup'){if(!isAdmin())throw new Error('Samo administrator izvozi rezervnu kopiju.');download('Balkan_rezervna_kopija_'+today()+'.json',JSON.stringify({schema:'balkan-imovina-v1',version:VERSION,exported_at:new Date().toISOString(),organization:state.org,data:Object.fromEntries(TABLES.map(k=>[k,D[k]]))},null,2),'application/json');return;}
 if(a==='file'){const r=D.documents.find(x=>x.id===id);if(state.demo||!r.storage_path)throw new Error('Prilog nije dostupan u demonstraciji.');el.disabled=true;try{const {data,error}=await client.storage.from(BUCKET).createSignedUrl(r.storage_path,120,{download:r.file_name||true});if(error)throw error;const a=document.createElement('a');a.href=data.signedUrl;a.target='_blank';a.rel='noopener noreferrer';a.click();}finally{el.disabled=false;}return;}
 if(a==='reset-demo'){if(!confirm('Vratiti početne demo podatke? Sve lokalne izmene u demonstraciji će biti obrisane.'))return;D=seedDemo();persistDemo();closeModal(true);state.profile.role='admin';render();toast('Vraćeni su početni demo podaci.');return;}
 if(a==='logout'||a==='exit-demo'){if(modal)closeModal(true);if(state.demo){state.demo=false;state.profile=null;state.route='dashboard';if(client){const {data,error}=await client.auth.getSession();if(error)throw error;if(data.session)await startSession();else renderLogin();}else renderLogin();}else{const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;state.profile=null;renderLogin();}return;}
 if(a==='show-config'){renderLogin(true);return;}if(a==='help'){help();return;}if(a==='download-sql'){download('schema.sql',document.getElementById('schema-source').textContent,'application/sql');return;}if(a==='download-vercel'){download('vercel.json',document.getElementById('vercel-source').textContent,'application/json');return;}
 if(a==='forgot'){const email=$('#login-email')?.value?.trim();if(!email){throw new Error('Prvo unesite e-mail adresu naloga.');}const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;toast('Ako nalog postoji, instrukcije za obnovu lozinke stići će na e-mail.');return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;handleAction(el).catch(error=>{if(modal)formError(error);else loginError(error);});});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.dataset.busy)return;f.dataset.busy='1';const buttons=[...f.querySelectorAll('button[type="submit"]')];buttons.forEach(x=>x.disabled=true);try{
 if(f.id==='record-form')await submitRecord();
 else if(f.id==='config-form'){const cfg=validateConfig($('#config-url').value.trim(),$('#config-key').value.trim());localStorage.setItem(CONFIG_KEY,JSON.stringify(cfg));await connect(cfg);}
 else if(f.id==='login-form'){const {error}=await client.auth.signInWithPassword({email:$('#login-email').value.trim(),password:$('#login-password').value});if(error)throw error;await startSession();}
 else if(f.id==='password-form'){const password=$('#new-password').value;if(password.length<12||password!==$('#confirm-password').value)throw new Error('Lozinke moraju biti iste i imati najmanje 12 znakova.');const {error}=await client.auth.updateUser({password});if(error)throw error;toast('Lozinka je promenjena.');if(recovery){recovery=false;await startSession();}else closeModal(true);}
 else if(f.id==='option-form'){if(!isAdmin())throw new Error('Pristup nije dozvoljen.');const old=modal.option;const flags={...(old?.flags??{})};for(const [id,key]of [['option-portfolio','portfolio'],['option-closed','closed'],['option-progress','in_progress']])if($('#'+id))flags[key]=$('#'+id).checked;const row={label:$('#option-label').value.trim(),sort_order:Number($('#option-sort').value),active:$('#option-active').checked,flags};if(!row.label)throw new Error('Unesite naziv.');if(!old){row.kind=modal.optionKind;row.code='custom_'+uid().slice(0,8);}await saveRecord('options',row,old);closeModal(true);render();toast('Lista je ažurirana.');}
 else if(f.id==='user-form'){if(!isAdmin())throw new Error('Pristup nije dozvoljen.');const p=modal.profile,role=$('#user-role').value,active=$('#user-active').checked,name=$('#user-name').value.trim();if(state.demo){Object.assign(state.profile,{role,active:true,display_name:name});}else{const {error}=await client.rpc('bg_manage_user',{p_user_id:p.id,p_role:role,p_active:active,p_display_name:name});if(error)throw error;}closeModal(true);if(!state.demo)await startSession();else{state.route='dashboard';render();}toast('Pristup je ažuriran.');}
 else if(f.id==='org-form'){if(!isAdmin())throw new Error('Pristup nije dozvoljen.');const name=$('#org-name').value.trim(),warning_days=Number($('#org-days').value);if(!name||!Number.isInteger(warning_days)||warning_days<0||warning_days>365)throw new Error('Proverite naziv i broj dana.');if(!state.demo){const {data,error}=await client.from('bg_organizations').update({name,warning_days}).eq('id',state.profile.org_id).select().single();if(error)throw error;state.org=data;}else state.org={...state.org,name,warning_days};render();toast('Podešavanja su sačuvana.');}
 }catch(error){if(modal)formError(error);else loginError(error);}finally{delete f.dataset.busy;buttons.forEach(x=>{if(x.isConnected)x.disabled=false;});}});
let searchTimer;
document.addEventListener('input',e=>{if(e.target.closest('#modal-root')){dirty=true;const flag=$('#draft-flag');if(flag)flag.textContent='Nesačuvane izmene';}if(e.target.dataset.search){clearTimeout(searchTimer);const term=e.target.value;searchTimer=setTimeout(()=>{state.page=1;if(e.target.dataset.search==='assets'){state.filters.q=term;const found=filterAssets(D,state.filters).sort((a,b)=>a.code.localeCompare(b.code,'sr'));$('#asset-count').textContent=countNoun(found.length,'nepokretnost','nepokretnosti','nepokretnosti');$('#asset-results').innerHTML=assetTable(found);}else{state.q=term;$('#entity-results').innerHTML=entityTable(state.route,D[state.route]);}},180);}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;state.page=1;render();}else if(e.target.id==='report-type'){state.report=e.target.value;state.page=1;render();}else if(e.target.id==='option-category'){state.category=e.target.value;render();}else if(e.target.id==='demo-role'){state.profile.role=e.target.value;closeModal(true);state.route='dashboard';render();}if(e.target.closest('#modal-root'))dirty=true;});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusable=$$('#modal-root button,#modal-root input,#modal-root select,#modal-root textarea,#modal-root a').filter(x=>!x.disabled&&x.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',e=>{if(modal&&dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>$('#offline')?.classList.add('hidden'));
window.addEventListener('offline',()=>$('#offline')?.classList.remove('hidden'));
window.addEventListener('afterprint',()=>{$('#print-root').innerHTML='';});
window.addEventListener('unhandledrejection',e=>{toast(friendly(e.reason),true);});
setInterval(()=>{if(state.profile?.active&&!state.demo&&!modal&&!loading&&document.visibilityState==='visible')reload().catch(e=>toast(friendly(e),true));},90000);
async function init(){renderLogin();let cfg=CONFIG.url&&CONFIG.key?CONFIG:null;if(!cfg){try{cfg=JSON.parse(localStorage.getItem(CONFIG_KEY));}catch{}}if(cfg){try{await connect(cfg);}catch(e){renderLogin(true);loginError(e);}}}
init();
